1	-- ============================================================================
2	-- APEX YUN PRO — 보장분석·상담 OS  |  0002_rls.sql  (재사용 모드)
3	-- RLS: 설계사(member)=본인 고객만, 팀장(leader)=우리 팀 조회, 관리자(admin)=전체.
4	--
5	-- ⚠️ 기존 CRM 함수를 재사용한다(재정의 금지):
6	--    public.is_admin()          role='admin' and active
7	--    public.is_leader()         role='leader' and active and team_id not null
8	--    public.my_team()           내 team_id
9	--    public.is_my_teammate(uid) 내가 팀장일 때 uid가 같은 팀인지
10	--    public.handle_new_user()   가입 시 profiles 자동 생성 (CRM 버전 유지)
11	-- 이 파일은 OS 신설 테이블에만 RLS/정책을 건다. CRM(profiles/teams/dbs/calls)은 손대지 않는다.
12	-- ============================================================================
13	
14	-- ── updated_at 자동 갱신 (OS 전용 함수명, 충돌 없음) ────────────────────────
15	create or replace function public.os_touch_updated_at()
16	returns trigger language plpgsql as $$
17	begin new.updated_at = now(); return new; end $$;
18	
19	drop trigger if exists trg_clients_touch on clients;
20	create trigger trg_clients_touch before update on clients
21	  for each row execute function public.os_touch_updated_at();
22	drop trigger if exists trg_cases_touch on analysis_cases;
23	create trigger trg_cases_touch before update on analysis_cases
24	  for each row execute function public.os_touch_updated_at();
25	
26	-- ── 고객 가시성 헬퍼 (OS 전용, 기존 함수 재사용해 판단) ─────────────────────
27	create or replace function public.can_see_client(cid uuid)
28	returns boolean language sql stable security definer set search_path = public as $$
29	  select public.is_admin()
30	      or exists (select 1 from clients c where c.id = cid and c.advisor_id = auth.uid())
31	      or exists (select 1 from clients c where c.id = cid and public.is_my_teammate(c.advisor_id));
32	$$;
33	
34	-- ── RLS 활성화 (OS 신설 테이블) ─────────────────────────────────────────────
35	alter table clients                enable row level security;
36	alter table households             enable row level security;
37	alter table documents              enable row level security;
38	alter table document_pages         enable row level security;
39	alter table extraction_runs        enable row level security;
40	alter table policies               enable row level security;
41	alter table coverages              enable row level security;
42	alter table proposals              enable row level security;
43	alter table proposal_plans         enable row level security;
44	alter table proposal_coverages     enable row level security;
45	alter table analysis_cases         enable row level security;
46	alter table comparison_scenarios   enable row level security;
47	alter table account_assessments    enable row level security;
48	alter table advisor_feedback       enable row level security;
49	alter table rule_candidates        enable row level security;
50	alter table knowledge_rules        enable row level security;
51	alter table report_versions        enable row level security;
52	alter table claims_cases           enable row level security;
53	alter table claims_evidence        enable row level security;
54	alter table reference_data         enable row level security;
55	alter table academy_modules        enable row level security;
56	alter table academy_quiz_questions enable row level security;
57	alter table academy_progress       enable row level security;
58	alter table academy_evaluations    enable row level security;
59	alter table ai_runs                enable row level security;
60	alter table audit_logs             enable row level security;
61	
62	-- ── clients (핵심 소유권 경계) ──────────────────────────────────────────────
63	drop policy if exists clients_read on clients;
64	-- 주의: 여기서는 can_see_client(id)를 쓰지 않는다. can_see_client는 내부에서
65	--   exists(select 1 from clients ...) 자기참조 서브쿼리를 돌리는데, INSERT ... RETURNING
66	--   (PostgREST의 return=representation) 시 같은 문장 안의 새 행을 그 서브쿼리가 못 봐서
67	--   42501을 낸다. clients 본체의 읽기 정책만은 동치 술어를 인라인해 자기참조를 없앤다.
68	--   (자식 테이블 documents 등은 다른 테이블 clients를 참조하므로 can_see_client 그대로 안전.)
69	create policy clients_read on clients for select to authenticated
70	  using (advisor_id = auth.uid() or public.is_admin() or public.is_my_teammate(advisor_id));
71	drop policy if exists clients_insert on clients;
72	create policy clients_insert on clients for insert to authenticated
73	  with check (advisor_id = auth.uid() or public.is_admin());
74	drop policy if exists clients_update on clients;
75	create policy clients_update on clients for update to authenticated
76	  using (advisor_id = auth.uid() or public.is_admin());
