-- ── updated_at 자동 갱신 (OS 전용 함수명, 충돌 없음) ────────────────────────
create or replace function public.os_touch_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

drop trigger if exists trg_clients_touch on clients;
create trigger trg_clients_touch before update on clients
  for each row execute function public.os_touch_updated_at();
drop trigger if exists trg_cases_touch on analysis_cases;
create trigger trg_cases_touch before update on analysis_cases
  for each row execute function public.os_touch_updated_at();

-- ── 고객 가시성 헬퍼 (OS 전용, 기존 함수 재사용해 판단) ─────────────────────
create or replace function public.can_see_client(cid uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or exists (select 1 from clients c where c.id = cid and c.advisor_id = auth.uid())
      or exists (select 1 from clients c where c.id = cid and public.is_my_teammate(c.advisor_id));
$$;

