create extension if not exists pgcrypto;

-- ── 역할 확장 (CHECK 재정의: 기존 값 보존 + 신규 2종) ────────────────────────
do $$ begin
  alter table public.profiles drop constraint if exists profiles_role_check;
  alter table public.profiles add constraint profiles_role_check
    check (role in ('admin','leader','member','education_manager','branch_manager'));
exception when undefined_table then null; end $$;

-- 신규 권한 판별 함수 (os_ 접두, 기존 is_admin/is_leader/my_team/is_my_teammate 재사용)
create or replace function public.os_is_branch() returns boolean
  language sql stable security definer set search_path=public as $$
  select exists(select 1 from public.profiles
                where id=auth.uid() and role in ('branch_manager','admin') and coalesce(active,true)); $$;

create or replace function public.os_is_edu() returns boolean
  language sql stable security definer set search_path=public as $$
  select exists(select 1 from public.profiles
                where id=auth.uid() and role in ('education_manager','admin') and coalesce(active,true)); $$;

-- 설계사(점수·학습·코칭) 가시성: 본인 / 관리자 / 지점장·교육 / 팀장이 팀원인 경우
create or replace function public.os_can_see_advisor(aid uuid) returns boolean
  language sql stable security definer set search_path=public as $$
  select aid = auth.uid()
      or public.is_admin()
      or public.os_is_branch()
      or public.os_is_edu()
      or (public.is_leader() and public.is_my_teammate(aid)); $$;

-- ── ENUM (idempotent) ───────────────────────────────────────────────────────
do $$ begin create type policy_change_type as enum
  ('endorsement','policyholder_change','beneficiary_change','payment_method_change',
   'main_reduce','rider_reduce','rider_delete','reduced_paidup','extended_term',
   'payment_suspension','automatic_premium_loan','substitute_payment','partial_withdrawal',
   'policy_loan','pension_conversion','reinstatement','surrender');
exception when duplicate_object then null; end $$;

do $$ begin create type consult_phase as enum ('pre','live','post');
exception when duplicate_object then null; end $$;

do $$ begin create type claim_status as enum
  ('intake','supplement','paid','reduced','denied','reappeal','closed');
exception when duplicate_object then null; end $$;

do $$ begin create type approval_status as enum ('pending','approved','rejected','withdrawn');
exception when duplicate_object then null; end $$;

