create policy branches_admin on branches for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- client 종속: financial/health/consultations/claims/aftercare → can_see_client
do $$ declare t text; begin
  foreach t in array array['financial_profiles','health_profiles','consultations','claims','aftercare_tasks'] loop
    execute format('drop policy if exists %I_by_client on %I', t, t);
    execute format(
      'create policy %I_by_client on %I for all to authenticated '
      'using (public.can_see_client(client_id)) with check (public.can_see_client(client_id))', t, t);
  end loop;
end $$;

-- policy_change_options: policy→client 조인
drop policy if exists pco_scope on policy_change_options;
create policy pco_scope on policy_change_options for all to authenticated
  using (exists (select 1 from policies p where p.id = policy_id and public.can_see_client(p.client_id)))
  with check (exists (select 1 from policies p where p.id = policy_id and public.can_see_client(p.client_id)));

-- consultation_transcripts: consultation→client 조인
drop policy if exists ctrans_scope on consultation_transcripts;
create policy ctrans_scope on consultation_transcripts for all to authenticated
  using (exists (select 1 from consultations c where c.id = consultation_id and public.can_see_client(c.client_id)))
  with check (exists (select 1 from consultations c where c.id = consultation_id and public.can_see_client(c.client_id)));

-- advisor 종속: scores/evidence/learning/quiz/coaching → os_can_see_advisor
drop policy if exists scores_scope on advisor_scores;
create policy scores_scope on advisor_scores for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists scores_write on advisor_scores;
create policy scores_write on advisor_scores for all to authenticated
  using (public.is_admin() or public.os_is_branch() or public.os_is_edu())
  with check (public.is_admin() or public.os_is_branch() or public.os_is_edu());

drop policy if exists scoreev_scope on score_evidence;
create policy scoreev_scope on score_evidence for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists scoreev_write on score_evidence;
create policy scoreev_write on score_evidence for all to authenticated
  using (public.is_admin() or public.os_is_branch() or public.os_is_edu())
  with check (public.is_admin() or public.os_is_branch() or public.os_is_edu());

drop policy if exists ltask_scope on learning_tasks;
create policy ltask_scope on learning_tasks for all to authenticated
  using (public.os_can_see_advisor(advisor_id)) with check (public.os_can_see_advisor(advisor_id));

drop policy if exists quizatt_scope on quiz_attempts;
