drop policy if exists quizatt_self on quiz_attempts;
create policy quizatt_self on quiz_attempts for insert to authenticated with check (advisor_id = auth.uid());

drop policy if exists coach_scope on coaching_records;
create policy coach_scope on coaching_records for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists coach_write on coaching_records;
create policy coach_write on coaching_records for all to authenticated
  using (public.is_admin() or public.os_is_branch() or (public.is_leader() and public.is_my_teammate(advisor_id)))
  with check (public.is_admin() or public.os_is_branch() or (public.is_leader() and public.is_my_teammate(advisor_id)));

-- approvals: 요청자 본인 조회 + 상위 검토/승인
drop policy if exists appr_read on approvals;
create policy appr_read on approvals for select to authenticated
  using (requested_by = auth.uid() or public.is_admin() or public.os_is_branch());
drop policy if exists appr_insert on approvals;
create policy appr_insert on approvals for insert to authenticated with check (requested_by = auth.uid());
drop policy if exists appr_decide on approvals;
create policy appr_decide on approvals for update to authenticated
  using (public.is_admin() or public.os_is_branch()) with check (public.is_admin() or public.os_is_branch());

-- manuals: 읽기 전원, 쓰기 관리자/교육
drop policy if exists manuals_read on manuals;
