alter table branches                enable row level security;
alter table financial_profiles      enable row level security;
alter table health_profiles         enable row level security;
alter table policy_change_options   enable row level security;
alter table consultations           enable row level security;
alter table consultation_transcripts enable row level security;
alter table advisor_scores          enable row level security;
alter table score_evidence          enable row level security;
alter table learning_tasks          enable row level security;
alter table quiz_attempts           enable row level security;
