alter table claims                  enable row level security;
alter table aftercare_tasks         enable row level security;
alter table manuals                 enable row level security;
alter table manual_revisions        enable row level security;
alter table notifications           enable row level security;
alter table insurance_products      enable row level security;
alter table coverage_dictionary     enable row level security;

-- updated_at 트리거 (os_touch_updated_at 은 0002에서 정의됨)
drop trigger if exists trg_consult_touch on consultations;
create trigger trg_consult_touch before update on consultations
  for each row execute function public.os_touch_updated_at();
drop trigger if exists trg_claims_touch on claims;
create trigger trg_claims_touch before update on claims
  for each row execute function public.os_touch_updated_at();

-- branches: 읽기 전원, 쓰기 관리자
drop policy if exists branches_read on branches;
create policy branches_read on branches for select to authenticated using (true);
drop policy if exists branches_admin on branches;
create policy branches_admin on branches for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- client 종속: financial/health/consultations/claims/aftercare → can_see_client
do $$ declare t text; begin
  foreach t in array array['financial_profiles','health_profiles','consultations','claims','aftercare_tasks'] loop
    execute format('drop policy if exists %I_by_client on %I', t, t);
    execute format(
      'create policy %I_by_client on %I for all to authenticated '
      'using (public.can_see_client(client_id)) with check (public.can_see_client(client_id))', t, t);
  end loop;
end $$;

-- policy_change_options: policy→client 조인
drop policy if exists pco_scope on policy_change_options;
create policy pco_scope on policy_change_options for all to authenticated
  using (exists (select 1 from policies p where p.id = policy_id and public.can_see_client(p.client_id)))
  with check (exists (select 1 from policies p where p.id = policy_id and public.can_see_client(p.client_id)));

-- consultation_transcripts: consultation→client 조인
drop policy if exists ctrans_scope on consultation_transcripts;
create policy ctrans_scope on consultation_transcripts for all to authenticated
  using (exists (select 1 from consultations c where c.id = consultation_id and public.can_see_client(c.client_id)))
  with check (exists (select 1 from consultations c where c.id = consultation_id and public.can_see_client(c.client_id)));

-- advisor 종속: scores/evidence/learning/quiz/coaching → os_can_see_advisor
drop policy if exists scores_scope on advisor_scores;
create policy scores_scope on advisor_scores for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists scores_write on advisor_scores;
create policy scores_write on advisor_scores for all to authenticated
  using (public.is_admin() or public.os_is_branch() or public.os_is_edu())
  with check (public.is_admin() or public.os_is_branch() or public.os_is_edu());

drop policy if exists scoreev_scope on score_evidence;
create policy scoreev_scope on score_evidence for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists scoreev_write on score_evidence;
create policy scoreev_write on score_evidence for all to authenticated
  using (public.is_admin() or public.os_is_branch() or public.os_is_edu())
  with check (public.is_admin() or public.os_is_branch() or public.os_is_edu());

drop policy if exists ltask_scope on learning_tasks;
create policy ltask_scope on learning_tasks for all to authenticated
  using (public.os_can_see_advisor(advisor_id)) with check (public.os_can_see_advisor(advisor_id));

drop policy if exists quizatt_scope on quiz_attempts;
create policy quizatt_scope on quiz_attempts for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists quizatt_self on quiz_attempts;
create policy quizatt_self on quiz_attempts for insert to authenticated with check (advisor_id = auth.uid());

drop policy if exists coach_scope on coaching_records;
create policy coach_scope on coaching_records for select to authenticated using (public.os_can_see_advisor(advisor_id));
drop policy if exists coach_write on coaching_records;
create policy coach_write on coaching_records for all to authenticated
  using (public.is_admin() or public.os_is_branch() or (public.is_leader() and public.is_my_teammate(advisor_id)))
  with check (public.is_admin() or public.os_is_branch() or (public.is_leader() and public.is_my_teammate(advisor_id)));

-- approvals: 요청자 본인 조회 + 상위 검토/승인
drop policy if exists appr_read on approvals;
create policy appr_read on approvals for select to authenticated
  using (requested_by = auth.uid() or public.is_admin() or public.os_is_branch());
drop policy if exists appr_insert on approvals;
create policy appr_insert on approvals for insert to authenticated with check (requested_by = auth.uid());
drop policy if exists appr_decide on approvals;
create policy appr_decide on approvals for update to authenticated
  using (public.is_admin() or public.os_is_branch()) with check (public.is_admin() or public.os_is_branch());

-- manuals: 읽기 전원, 쓰기 관리자/교육
drop policy if exists manuals_read on manuals;
create policy manuals_read on manuals for select to authenticated using (true);
drop policy if exists manuals_write on manuals;
create policy manuals_write on manuals for all to authenticated
  using (public.is_admin() or public.os_is_edu()) with check (public.is_admin() or public.os_is_edu());
drop policy if exists manrev_read on manual_revisions;
create policy manrev_read on manual_revisions for select to authenticated using (true);
drop policy if exists manrev_write on manual_revisions;
create policy manrev_write on manual_revisions for all to authenticated
  using (public.is_admin() or public.os_is_edu()) with check (public.is_admin() or public.os_is_edu());

-- notifications: 본인만
drop policy if exists notif_self on notifications;
create policy notif_self on notifications for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- 지식사전: 읽기 전원, 쓰기 관리자/교육
do $$ declare t text; begin
  foreach t in array array['insurance_products','coverage_dictionary'] loop
    execute format('drop policy if exists %I_read on %I', t, t);
    execute format('create policy %I_read on %I for select to authenticated using (true)', t, t);
    execute format('drop policy if exists %I_write on %I', t, t);
    execute format('create policy %I_write on %I for all to authenticated '
      'using (public.is_admin() or public.os_is_edu()) with check (public.is_admin() or public.os_is_edu())', t, t);
  end loop;
end $$;

