+function osReviewVsLabel(vs){for(var i=0;i<OS_VS.length;i++)if(OS_VS[i][0]===vs)return OS_VS[i][1];return vs;}
+function osReviewSave(approve){
+  var sb=osClient();if(!sb)return;
+  var ovl=document.getElementById('osOvl');if(!ovl)return;
+  var cards=ovl.querySelectorAll('.osrv-cov[data-cid]');
+  var updates=[];
+  cards.forEach(function(el){
+    var cid=el.getAttribute('data-cid');
+    var row=null;for(var i=0;i<OSR.rows.length;i++){if(OSR.rows[i].id===cid){row=OSR.rows[i];break;}}
+    if(!row)return;
+    var o=row.orig;
+    var nn=(el.querySelector('[data-f="normalized_name"]')||{}).value;nn=(nn||'').trim()||null;
+    var amRaw=(el.querySelector('[data-f="amount"]')||{}).value;var am=osNum(amRaw);
+    var cat=(el.querySelector('[data-f="category"]')||{}).value;cat=(cat||'')||null;
+    var changed=(nn!==(o.normalized_name||null))||(am!==(o.amount==null?null:Number(o.amount)))||(cat!==(o.category||null));
+    var vs=approve?'approved':(changed?'corrected':'reviewed');
+    updates.push({cid:cid,patch:{normalized_name:nn,amount:am,category:cat,verification_status:vs},changed:changed,before:o,after:{normalized_name:nn,amount:am,category:cat}});
+  });
+  var run=function(idx){
+    if(idx>=updates.length){
+      // 학습 루프 씨앗: 승인 시 교정 내역을 advisor_feedback 로 남길 수 있으나
+      // analysis_case 가 있어야 하므로 Phase 5 에서 연결. 여기서는 검수 상태만 확정.
+      toast(approve?'검수 완료 — 담보가 승인되었습니다.':'검수 내용을 저장했습니다.');
+      osCloseModal();osLoadDocs();return;
+    }
+    var u=updates[idx];
+    sb.from('coverages').update(u.patch).eq('id',u.cid).then(function(r){
+      if(r.error)toast('일부 저장 실패: '+r.error.message);
+      run(idx+1);
+    });
+  };
+  run(0);
+}

 /* 새 도구·재배치 반영해 현재 화면 갱신 */
 renderNav();updateKeyPill();

