var lastTab='dashboard';
function go(tab){
  if(tab==='finance'){
    mountFinance();
    document.body.classList.add('finance-mode');
    document.querySelectorAll('.tab-btn').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-tab')==='finance');});
    if(window.innerWidth<=880){$('sidebar').classList.remove('open');$('scrim').classList.remove('on');}
    return;
  }
  document.body.classList.remove('finance-mode');
  lastTab=tab;
  document.querySelectorAll('.tab-btn').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-tab')===tab);});
  var dyn=$('dynPane');
  if(tab==='dashboard')dyn.innerHTML=renderDashboard();
  else if(tab==='settings')dyn.innerHTML=renderSettings();
  else if(tab==='calc')dyn.innerHTML=renderCalcPage();
  else if(tab==='clients'){dyn.innerHTML=renderClientsPage();osClientsAfterRender();}
  else dyn.innerHTML=renderToolPage(tab);
  $('main').scrollTop=0;
  if(window.innerWidth<=880){$('sidebar').classList.remove('open');$('scrim').classList.remove('on');}
}
function exitFinance(){go(lastTab||'dashboard');}

