/* ════════ 재무설계 모듈 (iframe) ════════ */
function b64ToUtf8(b64){
  var bin=atob(b64),bytes=new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  try{return new TextDecoder('utf-8').decode(bytes);}
  catch(e){return decodeURIComponent(escape(bin));}
}
function getFinanceHtml(){
  var raw=$('finB64')?$('finB64').textContent.trim():'';
  if(!raw||raw==='__FIN_B64__')return '<body style="font-family:sans-serif;padding:40px;color:#374151"><h2>재무설계 모듈이 로드되지 않았습니다</h2><p>이 파일이 빌드 과정에서 모듈을 포함하지 못했습니다.</p></body>';
  try{return b64ToUtf8(raw);}catch(e){return '<body><pre>'+e+'</pre></body>';}
}

