function renderToolPage(tab){
  var meta=TAB_META[tab]||{tag:'TOOL',title:navTitle(tab),desc:''};
  var body='<div class="tab-pane on"><div class="page-hd"><div class="page-tag">'+esc(meta.tag)+'</div>'+
    '<div class="page-title">'+esc(meta.title)+'</div>'+(meta.desc?'<div class="page-desc">'+esc(meta.desc)+'</div>':'')+'</div>';
  var any=false;
  // 1) PDF 분석 도구
  if(typeof PDF_TOOLS!=='undefined')PDF_TOOLS.forEach(function(p){if(p.tab===tab){body+=renderPdfTool(p);any=true;}});
  // 2) 커스텀 도구(키워드 조합기·디지털 명함 등)
  if(typeof CUSTOM!=='undefined')CUSTOM.forEach(function(c){if(c.tab===tab){body+=c.render();any=true;}});
  // 3) 링크 보드(외부 시스템)
  if(typeof LINKS!=='undefined')LINKS.forEach(function(l){if(l.tab===tab){body+=renderLinkCard(l);any=true;}});
  // 4) AI 생성기
  GEN.forEach(function(g){if(g.tab===tab){body+=renderTool(g);any=true;}});
  if(!any)body+='<div class="card"><div class="card-body"><div class="notice" style="color:var(--ink-4);background:var(--ink-8);border-color:var(--ink-7)">이 도구는 곧 추가됩니다. 빌드 키트(CLAUDE.md·SPEC.md)에 명세가 있습니다.</div></div></div>';
  body+='</div>';
  return body;
}
function navTitle(tab){var t=tab;TABS.forEach(function(g){g.items.forEach(function(it){if(it.id===tab)t=it.title;});});return t;}

function renderTool(g){
  var fh='';
  var cols=g.fields.length>2;
  g.fields.forEach(function(f){
    var span=(f.span||f.type==='textarea')?' span2':'';
    fh+='<div class="fld'+span+'" data-field="'+f.name+'">';
    fh+='<label>'+esc(f.label)+(f.hint?' <span class="hint">'+esc(f.hint)+'</span>':'')+'</label>';
    if(f.type==='textarea'){
      fh+='<textarea data-input="'+f.name+'" placeholder="'+esc(f.ph||'')+'"></textarea>';
    }else if(f.type==='select'){
      fh+='<select data-input="'+f.name+'">'+f.options.map(function(o){return '<option>'+esc(o)+'</option>';}).join('')+'</select>';

