function renderClientsPage(){
  if(!OS.profile){
    return '<div class="osc-wrap"><div class="osc-gate">'+
      '<div class="ic">🔒</div><h3>로그인이 필요합니다</h3>'+
      '<p>고객 보장분석 프로젝트는 설계사 계정으로 로그인해야 열립니다.<br>기존 CRM 계정으로 바로 로그인할 수 있어요.</p>'+
      '<button class="os-btn" onclick="osOpenModal()">로그인 / 계정</button>'+
    '</div></div>';
  }
  if(OSC.view==='detail'&&OSC.current)return osClientDetailHtml(OSC.current);
  return '<div class="osc-wrap">'+
    '<div class="osc-bar">'+
      '<input class="osc-search" id="oscSearch" placeholder="고객 이름 검색…" oninput="osClientsFilter(this.value)" value="'+osEsc(OSC.q)+'"/>'+
