  if(OSC.view==='detail'&&OSC.current){osBindDrop();osLoadDocs();osLoadAnalysis();}
}
function osLoadClients(){
  var sb=osClient();if(!sb)return;
  sb.from('clients').select('id,name_masked,consent_status,created_at').order('created_at',{ascending:false}).then(function(r){
    if(r.error){osSetList('<div class="osc-empty">목록을 불러오지 못했습니다: '+osEsc(r.error.message)+'</div>');return;}
    OSC.list=r.data||[];osRenderList();
