}
function osRenderList(){
  var q=(OSC.q||'').trim();
  var rows=OSC.list.filter(function(c){return !q||(''+(c.name_masked||'')).indexOf(q)>=0;});
  if(!rows.length){osSetList('<div class="osc-empty">'+(q?'검색 결과가 없습니다.':'아직 등록된 고객이 없습니다. 우측 상단 <b>+ 새 고객</b>으로 시작하세요.')+'</div>');return;}
  var h='';
  rows.forEach(function(c){
    var nm=c.name_masked||'(이름 없음)';
    var cs=c.consent_status||'none';
    h+='<div class="osc-item" onclick="osOpenClient(\''+c.id+'\')">'+
        '<div class="osc-av">'+osEsc(nm.charAt(0))+'</div>'+
        '<div class="osc-meta"><div class="osc-nm">'+osEsc(nm)+'</div><div class="osc-mn">'+osFmtDate(c.created_at)+' 등록</div></div>'+
        '<span class="osc-badge '+cs+'">'+osConsentLabel(cs)+'</span>'+
      '</div>';
