/* count 쿼리 — 테이블/컬럼 미존재 시 graceful(skipped) */
function osCountQ(sb,tbl,build){
  return new Promise(function(res){
    try{
      var q=sb.from(tbl).select('id',{count:'exact',head:true});
      if(build)q=build(q);
      q.then(function(r){if(r&&r.error){res({skipped:true});}else{res({n:(r&&r.count)||0});}},function(){res({skipped:true});});
    }catch(e){res({skipped:true});}
  });
}
