    {key:'team_after',icon:'🩹',label:'팀 미완료 사후관리',tab:'branch_coach',run:function(sb){return osCountQ(sb,'aftercare_tasks',function(q){return q.neq('status','done').lte('due_date',today);});},ev:'팀 aftercare_tasks(기한 도래)'}
  ];
