    {key:'appr_high',icon:'⚠️',label:'고위험 승인 대기',tab:'hq',run:function(sb){return osCountQ(sb,'approvals',function(q){return q.eq('status','pending').eq('risk_level','high');});},ev:'approvals(high, pending)'},
    {key:'appr_all',icon:'📥',label:'전체 승인 대기',tab:'hq',run:function(sb){return osCountQ(sb,'approvals',function(q){return q.eq('status','pending');});},ev:'approvals.status=pending'},
    {key:'restricted',icon:'🛑',label:'상담제한 설계사',tab:'hq',run:function(sb){return osCountQ(sb,'advisor_scores',function(q){return q.eq('restricted',true);});},ev:'advisor_scores.restricted(준법위험)'}
