function osScoreGrade(t){t=t||0;if(t>=90)return['APEX PRO','#059669'];if(t>=80)return['신뢰 설계사','#1A56DB'];if(t>=70)return['성장 설계사','#0891B2'];if(t>=60)return['집중 코칭','#D97706'];return['기본과정 재교육','#DC2626'];}
