    '<div style="flex:1;min-width:180px"><div style="font-size:12px;color:#9CA3AF;font-weight:700">'+osEsc(row.period||'')+' 평가</div>'+
      '<div style="font-size:19px;font-weight:800;color:'+g[1]+';margin-top:2px">'+osEsc(g[0])+'</div>'+
      '<div style="margin-top:5px">'+deltaHtml+'</div></div></div>';
  var bars='<div class="osc-panel" style="margin-top:12px"><div style="font-size:13px;font-weight:800;color:#1C2434;margin-bottom:12px">8영역 상세</div>';
  OS_SCORE_AREAS.forEach(function(a){
    var v=(bd&&typeof bd[a[0]]==='number')?bd[a[0]]:null;var max=a[2];
    var pct=v===null?0:Math.max(0,Math.min(100,(v/max)*100));
