      '<div style="height:8px;background:#F1F3F5;border-radius:20px;overflow:hidden"><div style="height:100%;width:'+pct+'%;background:'+col+';border-radius:20px"></div></div></div>';
  });
  bars+='<div class="notice" style="margin-top:6px;color:var(--ink-4);background:var(--ink-8);border-color:var(--ink-7);font-size:11.5px">각 가감점은 <b>score_evidence</b>(근거)로 연결되며, 임의 입력만으로 확정되지 않습니다.</div></div>';
  box.innerHTML=head+restr+bars;
}

