  });
}
/* 역할별 능동 신호 정의 */
function osAsstSpecs(role,uid,today){
  var adv=[
    {key:'schedule',icon:'📅',label:'오늘·지연 상담 후속',tab:'clients',run:function(sb){return osCountQ(sb,'consultations',function(q){return q.eq('advisor_id',uid).lte('due_date',today);});},ev:'consultations.due_date ≤ 오늘'},
    {key:'reconnect',icon:'🔔',label:'재연락 알림',tab:'clients',run:function(sb){return osCountQ(sb,'notifications',function(q){return q.eq('user_id',uid).eq('kind','reconnect').is('read_at',null);});},ev:'notifications(kind=재연락, 미확인)'},
    {key:'aftercare',icon:'🩹',label:'미완료 사후관리',tab:'claims',run:function(sb){return osCountQ(sb,'aftercare_tasks',function(q){return q.eq('assignee_id',uid).neq('status','done').lte('due_date',today);});},ev:'aftercare_tasks(기한 도래, 미완료)'},
    {key:'claim_supp',icon:'🧾',label:'청구 보완 필요',tab:'claims',run:function(sb){return osCountQ(sb,'claims',function(q){return q.eq('status','supplement');});},ev:'claims.status=보완'},
    {key:'review',icon:'🔍',label:'담보 검수 대기',tab:'clients',run:function(sb){return osCountQ(sb,'extraction_runs',function(q){return q.is('approved_at',null);});},ev:'extraction_runs(미검수)'},
    {key:'doc',icon:'📄',label:'서류 처리 대기',tab:'clients',run:function(sb){return osCountQ(sb,'documents',function(q){return q.in('parse_status',['pending','failed']);});},ev:'documents(대기/실패)'},
    {key:'learning',icon:'🎓',label:'성장 과제',tab:'academy',run:function(sb){return osCountQ(sb,'learning_tasks',function(q){return q.eq('advisor_id',uid).eq('status','open');});},ev:'learning_tasks.status=open'}
  ];
  var lead=[
    {key:'team_review',icon:'🔍',label:'팀 검수 대기',tab:'branch_coach',run:function(sb){return osCountQ(sb,'extraction_runs',function(q){return q.is('approved_at',null);});},ev:'팀 extraction_runs(미검수)'},
    {key:'coach',icon:'🧑‍🏫',label:'코칭 필요(상담제한)',tab:'branch_coach',run:function(sb){return osCountQ(sb,'advisor_scores',function(q){return q.eq('restricted',true);});},ev:'advisor_scores.restricted'},
    {key:'appr_wait',icon:'📥',label:'승인 대기(팀)',tab:'branch_coach',run:function(sb){return osCountQ(sb,'approvals',function(q){return q.eq('status','pending');});},ev:'approvals.status=pending'},
    {key:'team_after',icon:'🩹',label:'팀 미완료 사후관리',tab:'branch_coach',run:function(sb){return osCountQ(sb,'aftercare_tasks',function(q){return q.neq('status','done').lte('due_date',today);});},ev:'팀 aftercare_tasks(기한 도래)'}
  ];
  var hq=[
    {key:'appr_high',icon:'⚠️',label:'고위험 승인 대기',tab:'hq',run:function(sb){return osCountQ(sb,'approvals',function(q){return q.eq('status','pending').eq('risk_level','high');});},ev:'approvals(high, pending)'},
    {key:'appr_all',icon:'📥',label:'전체 승인 대기',tab:'hq',run:function(sb){return osCountQ(sb,'approvals',function(q){return q.eq('status','pending');});},ev:'approvals.status=pending'},
    {key:'restricted',icon:'🛑',label:'상담제한 설계사',tab:'hq',run:function(sb){return osCountQ(sb,'advisor_scores',function(q){return q.eq('restricted',true);});},ev:'advisor_scores.restricted(준법위험)'}
  ];
  if(osIsHQ(role))return hq.concat(adv);
  if(osIsLead(role))return lead.concat(adv);
  return adv;
}
function osAssistantAfterRender(){
  if(!OS.profile)return;
  var sb=osClient();var box=document.getElementById('osAsstBody');if(!sb||!box)return;
  var uid=OS.session.user.id;var today=osTodayStr();var role=osRole();
  var specs=osAsstSpecs(role,uid,today);
  Promise.all(specs.map(function(s){return s.run(sb);})).then(function(results){
    osRenderAsstCards(box,specs,results);
  },function(){if(box)box.innerHTML='<div class="osrv-warn">업무 집계 중 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.</div>';});
}
function osRenderAsstCards(box,specs,results){
  var act=[],quiet=[],skip=0;
  specs.forEach(function(s,i){var r=results[i]||{};if(r.skipped){skip++;return;}if((r.n||0)>0)act.push({s:s,n:r.n});else quiet.push(s);});
  var h='';
  if(act.length){
    h+='<div style="font-size:13px;font-weight:800;color:#1C2434;margin:2px 0 10px">지금 처리할 일 <span style="color:#DC2626">'+act.length+'</span>건</div>';
    h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">';
    act.forEach(function(a){
      h+='<button onclick="go(\''+a.s.tab+'\')" style="text-align:left;background:#fff;border:1px solid #E9EAEC;border-radius:12px;padding:13px 15px;cursor:pointer;transition:all .12s" onmouseover="this.style.borderColor=\'#1A56DB\';this.style.boxShadow=\'0 4px 14px rgba(26,86,219,.10)\'" onmouseout="this.style.borderColor=\'#E9EAEC\';this.style.boxShadow=\'none\'">'+
        '<div style="display:flex;align-items:center;gap:8px"><span style="font-size:18px">'+a.s.icon+'</span>'+
        '<span style="font-size:13.5px;font-weight:800;color:#191F28">'+osEsc(a.s.label)+'</span>'+
        '<span style="margin-left:auto;font-size:12px;font-weight:800;color:#fff;background:#DC2626;border-radius:20px;padding:2px 9px">'+a.n+'</span></div>'+
        '<div style="font-size:11px;color:#9CA3AF;margin-top:8px">근거: '+osEsc(a.s.ev)+'</div>'+
        '<div style="font-size:11.5px;font-weight:700;color:#1A56DB;margin-top:6px">바로가기 →</div>'+
      '</button>';
    });
    h+='</div>';
  }else{
    h+='<div class="osc-panel" style="text-align:center;color:#059669"><div style="font-size:26px">✅</div><div style="font-size:14px;font-weight:800;margin-top:6px">지금 즉시 처리할 항목이 없습니다.</div><div style="font-size:12px;color:#6B7280;margin-top:4px">데이터 기준으로 밀린 업무가 없습니다. 고객·상담·학습을 이어가세요.</div></div>';
  }
  if(quiet.length){
    h+='<div style="font-size:12px;font-weight:700;color:#6B7280;margin:16px 0 8px">확인 완료 · 0건</div><div style="display:flex;flex-wrap:wrap;gap:6px">';
    quiet.forEach(function(s){h+='<span style="font-size:11.5px;color:#6B7280;background:#F3F4F6;border-radius:20px;padding:4px 11px">'+s.icon+' '+osEsc(s.label)+' 0</span>';});
    h+='</div>';
  }
  if(skip){
    h+='<div class="osrv-warn" style="margin-top:14px;font-size:11.5px">일부 항목('+skip+'개)은 <b>0004 마이그레이션 적용 후</b> 집계됩니다. 테이블이 아직 없어 건너뜁니다.</div>';
  }
  h+='<div class="notice" style="margin-top:14px;color:var(--ink-4);background:var(--ink-8);border-color:var(--ink-7);font-size:11.5px">이 목록은 AI가 아니라 실제 DB 집계로 만들어집니다. 상담 전 "반드시 물을 질문"은 <b>고객 360 상세</b>에서 결측 항목을 기준으로 생성됩니다.</div>';
  box.innerHTML=h;
}

/* ── 100점 설계사 성장 ───────────────────────────────────────────────── */
var OS_SCORE_AREAS=[
  ['activity','활동 실행력',15],['understanding','고객 이해력',15],['interpret','보험 해석력',20],
  ['design','상담 설계력',15],['comm','설명·소통',10],['compliance','계약 정확성·준법',10],
  ['claims','청구·사후관리',10],['growth','성장·조직 기여',5]
];
function osScoreGrade(t){t=t||0;if(t>=90)return['APEX PRO','#059669'];if(t>=80)return['신뢰 설계사','#1A56DB'];if(t>=70)return['성장 설계사','#0891B2'];if(t>=60)return['집중 코칭','#D97706'];return['기본과정 재교육','#DC2626'];}
function renderGrowth(){
  if(!OS.profile)return osPage('내 성장','100점 성장','로그인 후 8영역 점수·등급·다음 행동이 열립니다.',osLoginGate('100점 성장 화면은 로그인 후 이용할 수 있습니다.'));
  return osPage('내 성장','100점 설계사 성장','활동·이해·해석·설계·소통·준법·청구·기여 8영역을 근거 기반으로 집계합니다. 임의 입력만으로 확정하지 않습니다.',
    '<div id="osGrowthBody"><div class="osc-loading">내 점수를 불러오는 중…</div></div>');
}
function osGrowthAfterRender(){
  if(!OS.profile)return;
  var sb=osClient();var box=document.getElementById('osGrowthBody');if(!sb||!box)return;
  var uid=OS.session.user.id;
  sb.from('advisor_scores').select('total,breakdown_json,grade,prev_delta,restricted,period,evaluated_at').eq('advisor_id',uid).order('evaluated_at',{ascending:false}).limit(1).then(function(r){
    if(r&&r.error){osRenderGrowthEmpty(box,'not_ready');return;}
    var row=(r&&r.data&&r.data[0])||null;
    if(!row){osRenderGrowthEmpty(box,'no_score');return;}
    osRenderGrowth(box,row);
  },function(){osRenderGrowthEmpty(box,'not_ready');});
}
function osRenderGrowthEmpty(box,why){
  var msg=why==='not_ready'
    ? '점수 테이블이 아직 준비되지 않았습니다(0004 마이그레이션 적용 후 표시).'
    : '아직 이번 주 평가가 없습니다. 활동·상담·검수·학습 데이터가 쌓이면 관리자 검토를 거쳐 점수가 산정됩니다.';
  var areas='';
  OS_SCORE_AREAS.forEach(function(a){areas+='<div style="display:flex;justify-content:space-between;font-size:12.5px;color:#374151;padding:7px 0;border-bottom:1px solid #F1F3F5"><span>'+osEsc(a[1])+'</span><span style="color:#9CA3AF">— / '+a[2]+'</span></div>';});
  box.innerHTML='<div class="osc-panel"><div class="osrv-warn" style="margin-bottom:12px">'+osEsc(msg)+'</div>'+
    '<div style="font-size:12px;font-weight:800;color:#1C2434;margin-bottom:6px">8영역 배점</div>'+areas+
    '<div class="notice" style="margin-top:12px;color:var(--ink-4);background:var(--ink-8);border-color:var(--ink-7);font-size:11.5px">각 점수는 <b>자동집계 + 관리자 조정</b>으로 산정되며, 모든 가감점은 근거(score_evidence)에 연결됩니다.</div></div>';
}
function osRenderGrowth(box,row){
  var total=row.total||0;var g=osScoreGrade(total);var bd=row.breakdown_json||{};
  var delta=row.prev_delta;
  var deltaHtml=(delta===null||typeof delta==='undefined')?'':('<span style="font-size:12px;font-weight:800;color:'+(delta>=0?'#059669':'#DC2626')+'">지난주 대비 '+(delta>=0?'+':'')+delta+'</span>');
  var ring='conic-gradient('+g[1]+' '+(total*3.6)+'deg,#EEF0F3 0deg)';
  var restr=row.restricted?'<div class="osrv-warn" style="margin-top:12px;border-color:#FCA5A5;background:#FEF2F2;color:#B91C1C"><b>🛑 상담제한</b> — 중대한 준법 이슈로 상담이 제한된 상태입니다. 해제는 관리자 승인이 필요합니다.</div>':'';
  var head='<div class="osc-panel" style="display:flex;align-items:center;gap:18px;flex-wrap:wrap">'+
    '<div style="width:104px;height:104px;border-radius:50%;background:'+ring+';display:flex;align-items:center;justify-content:center">'+
      '<div style="width:80px;height:80px;border-radius:50%;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center">'+
        '<div style="font-size:24px;font-weight:800;color:'+g[1]+'">'+total+'</div><div style="font-size:10px;color:#9CA3AF">/ 100</div></div></div>'+
    '<div style="flex:1;min-width:180px"><div style="font-size:12px;color:#9CA3AF;font-weight:700">'+osEsc(row.period||'')+' 평가</div>'+
      '<div style="font-size:19px;font-weight:800;color:'+g[1]+';margin-top:2px">'+osEsc(g[0])+'</div>'+
      '<div style="margin-top:5px">'+deltaHtml+'</div></div></div>';
  var bars='<div class="osc-panel" style="margin-top:12px"><div style="font-size:13px;font-weight:800;color:#1C2434;margin-bottom:12px">8영역 상세</div>';
  OS_SCORE_AREAS.forEach(function(a){
    var v=(bd&&typeof bd[a[0]]==='number')?bd[a[0]]:null;var max=a[2];
    var pct=v===null?0:Math.max(0,Math.min(100,(v/max)*100));
    var col=v===null?'#E5E7EB':(pct>=80?'#059669':(pct>=50?'#1A56DB':'#D97706'));
    bars+='<div style="margin-bottom:11px"><div style="display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:4px"><span style="color:#374151;font-weight:600">'+osEsc(a[1])+'</span><span style="color:#6B7280;font-weight:700">'+(v===null?'—':v)+' / '+max+'</span></div>'+
      '<div style="height:8px;background:#F1F3F5;border-radius:20px;overflow:hidden"><div style="height:100%;width:'+pct+'%;background:'+col+';border-radius:20px"></div></div></div>';
  });
  bars+='<div class="notice" style="margin-top:6px;color:var(--ink-4);background:var(--ink-8);border-color:var(--ink-7);font-size:11.5px">각 가감점은 <b>score_evidence</b>(근거)로 연결되며, 임의 입력만으로 확정되지 않습니다.</div></div>';
  box.innerHTML=head+restr+bars;
}

