function osPillClick(){if(OS.profile)osLogout();else osOpenModal();}

var osMode='login';
function osModalHtml(){
  return '<div class="os-modal">'+
    '<button class="os-x" onclick="osCloseModal()">&times;</button>'+
    '<div class="hd"><h3>APEX 상담 OS 로그인</h3><p>설계사 계정으로 로그인하면 고객 보장분석 프로젝트가 열립니다.</p></div>'+
    '<div class="bd">'+
      '<div class="os-tabs"><button id="osTabLogin" class="on" onclick="osAuthTab(\'login\')">로그인</button><button id="osTabSignup" onclick="osAuthTab(\'signup\')">계정 등록</button></div>'+
      '<div class="os-fld" id="osNameFld" style="display:none"><label>이름</label><input id="osName" placeholder="홍길동"/></div>'+
      '<div class="os-fld"><label>이메일</label><input id="osEmail" type="email" placeholder="you@example.com" autocomplete="username"/></div>'+
      '<div class="os-fld"><label>비밀번호</label><input id="osPw" type="password" placeholder="••••••••" autocomplete="current-password"/></div>'+
      '<div class="os-err" id="osErr"></div>'+
      '<button class="os-btn" id="osSubmit" onclick="osSubmit()">로그인</button>'+
    '</div></div>';
}
function osOpenModal(){
  var ovl=document.getElementById('osOvl');
  if(!ovl){ovl=document.createElement('div');ovl.id='osOvl';ovl.className='os-ovl';ovl.innerHTML=osModalHtml();document.body.appendChild(ovl);
    ovl.addEventListener('click',function(e){if(e.target===ovl)osCloseModal();});}
  ovl.classList.add('on');osAuthTab('login');
  var em=document.getElementById('osEmail');if(em)em.focus();
}
function osCloseModal(){var o=document.getElementById('osOvl');if(o)o.classList.remove('on');}
function osAuthTab(m){
  osMode=m;
  var l=document.getElementById('osTabLogin'),s=document.getElementById('osTabSignup');
  if(l)l.className=(m==='login'?'on':'');if(s)s.className=(m==='signup'?'on':'');
  var nf=document.getElementById('osNameFld');if(nf)nf.style.display=(m==='signup'?'block':'none');
  var b=document.getElementById('osSubmit');if(b)b.textContent=(m==='signup'?'계정 등록':'로그인');
  osErr('');
}
function osErr(msg){var e=document.getElementById('osErr');if(e)e.textContent=msg||'';}
function osLoginErr(m){if(/Invalid login/i.test(m||''))return '이메일 또는 비밀번호가 올바르지 않습니다.';if(/Email not confirmed/i.test(m||''))return '이메일 인증이 완료되지 않았습니다.';return m;}
function osSubmit(){
  var sb=osClient();if(!sb){osErr('서버 연결 모듈을 불러오지 못했습니다. 네트워크를 확인하세요.');return;}
  var email=(osVal('osEmail')||'').trim(),pw=osVal('osPw');
  if(!email||!pw){osErr('이메일과 비밀번호를 입력하세요.');return;}
  var btn=document.getElementById('osSubmit');if(btn){btn.disabled=true;btn.textContent='처리 중…';}
  var done=function(){if(btn){btn.disabled=false;btn.textContent=(osMode==='signup'?'계정 등록':'로그인');}};
  if(osMode==='signup'){
    var name=(osVal('osName')||'').trim();
    sb.auth.signUp({email:email,password:pw,options:{data:{name:name}}}).then(function(r){
      done();if(r.error){osErr(r.error.message);return;}
      osErr('');toast('계정이 생성되었습니다. 관리자 승인 후 이용하세요.');osAuthTab('login');
    });
  }else{
    sb.auth.signInWithPassword({email:email,password:pw}).then(function(r){
      done();if(r.error){osErr(osLoginErr(r.error.message));return;}osCloseModal();
    });
  }
}
function osLogout(){var sb=osClient();if(sb)sb.auth.signOut();}
function osLoadProfile(){
  var sb=osClient();if(!sb||!OS.session){OS.profile=null;osRenderPill();return;}
  var uid=OS.session.user&&OS.session.user.id;
  sb.from('profiles').select('id,name,role,active,team_id').eq('id',uid).single().then(function(r){
    if(r.error||!r.data){OS.profile=null;osRenderPill();return;}
    if(r.data.active===false){toast('비활성화된 계정입니다. 관리자에게 문의하세요.');sb.auth.signOut();return;}
    OS.profile=r.data;osRenderPill();osOnLogin();
  });
}
function osOnLogin(){toast('로그인됨 · '+osRoleLabel(OS.profile.role));osRefreshIfClients();}
/* 로그인/로그아웃 후: 역할 메뉴 갱신 + 역할·데이터 민감 화면만 재렌더(작성 중 도구는 보존) */
function osRefreshIfClients(){
  if(typeof renderNav==='function')renderNav();
  var t=(typeof currentTab==='function')?currentTab():'home';
  var refresh={home:1,dashboard:1,assistant:1,growth:1,clients:1,branch_coach:1,hq:1,interpret:1,contracts:1,claims:1,academy:1,manual:1};
  if(refresh[t]&&typeof go==='function')go(t);
}
function osBootAuth(){
  osRenderPill();
  var sb=osClient();if(!sb)return;
  sb.auth.onAuthStateChange(function(evt,s){OS.session=s;if(s){osLoadProfile();}else{OS.profile=null;osRenderPill();osRefreshIfClients();}});
