760	function callClaude(system,user,maxTokens){
761	  var payload={model:getModel(),max_tokens:maxTokens||2000,system:system,messages:[{role:'user',content:user}]};
762	  var url,headers;
763	  if(getConn()==='proxy'){
764	    var px=getProxy();
765	    if(!px)return Promise.reject(new Error('NO_KEY'));
766	    url=px;headers={'Content-Type':'application/json'};   /* 프록시 서버가 키를 보관 */
767	  }else{
768	    var key=getKey();
769	    if(!key)return Promise.reject(new Error('NO_KEY'));
770	    url='https://api.anthropic.com/v1/messages';
771	    headers={'Content-Type':'application/json','x-api-key':key,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'};
772	  }
773	  return fetch(url,{method:'POST',headers:headers,body:JSON.stringify(payload)}).then(function(res){
774	    return res.text().then(function(txt){
775	      if(!res.ok){
776	        var msg=txt;
777	        try{var j=JSON.parse(txt);if(j.error&&j.error.message)msg=j.error.message;else if(j.message)msg=j.message;}catch(e){}
778	        var er=new Error(msg);er.status=res.status;throw er;
779	      }
780	      var data=JSON.parse(txt);
781	      /* 프록시가 {text:"..."} 또는 표준 {content:[...]} 둘 다 허용 */
782	      if(typeof data.text==='string')return data.text;
783	      var out=(data.content||[]).filter(function(b){return b.type==='text';}).map(function(b){return b.text;}).join('\n');
784	      return out;
785	    });
786	  });
787	}
