790	function inlineMd(s){s=esc(s);s=s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');return s;}
791	function renderMd(md){
792	  var lines=String(md==null?'':md).replace(/\r/g,'').split('\n');
793	  var out=[],inList=false,listClass='';
794	  function close(){if(inList){out.push('</ul>');inList=false;listClass='';}}
795	  function isTableSep(s){return /^\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?$/.test(s);}
