function isAutoConnected(){return !!window.__APEX_LOCKED;}
function getKey(){return LS.get('apikey','');}
function getModel(){return (APEX_CONFIG&&APEX_CONFIG.model)?APEX_CONFIG.model:LS.get('model','claude-sonnet-4-6');}
function getConn(){return LS.get('conn','direct');}      /* 'direct' | 'proxy' */
function getProxy(){return LS.get('proxy','');}
function aiReady(){return getConn()==='proxy'?!!getProxy():!!getKey();}
var DEFAULT_PERSONA="당신은 'APEX-YUNPRO' 브랜드 전속 콘텐츠 카피라이터입니다.\n- 운영자: 에이플러스에셋 온탑본부 윤시현 본부장 (10년 경력 보험·재무설계 전문가)\n- 슬로건: \"보험을 파는 설계사가 아닌, 삶을 설계하는 설계사\"\n- 채널: 유튜브 '삶을 설계하다', 인스타그램 전문 콘텐츠\n- 주력 고객: 40~60대 자산가, 맞춤 보장 설계\n- 핵심 상담 프레임: '치료비 통장' (큰 병이 와도 가계를 지키는 별도의 보장 자산)\n\n[작성 원칙]\n1. 신뢰감 있고 따뜻하면서 전문적인 톤. 과장·자극적 표현 금지.\n2. 보험업법·보험광고 규정 준수: 수익·환급 단정 보장 표현, 타사 비방, 불안 조장 금지.\n3. 구체적 수치·사례는 '예시'임을 명시. 확정 정보처럼 단정하지 않기.\n4. 한국어, 자연스러운 구어체. 설계사가 그대로 활용할 수 있는 완성형 문장.\n5. 마지막엔 항상 부드러운 행동 유도(CTA) 한 줄.";
function getPersona(){return LS.get('persona',DEFAULT_PERSONA);}

/* ════════ Claude API ════════ */
function callClaude(system,user,maxTokens){
  var payload={model:getModel(),max_tokens:maxTokens||2000,system:system,messages:[{role:'user',content:user}]};
  var url,headers;
  if(getConn()==='proxy'){
    var px=getProxy();
    if(!px)return Promise.reject(new Error('NO_KEY'));
    url=px;headers={'Content-Type':'application/json'};   /* 프록시 서버가 키를 보관 */
  }else{
    var key=getKey();
    if(!key)return Promise.reject(new Error('NO_KEY'));
    url='https://api.anthropic.com/v1/messages';
    headers={'Content-Type':'application/json','x-api-key':key,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'};
  }
  return fetch(url,{method:'POST',headers:headers,body:JSON.stringify(payload)}).then(function(res){
    return res.text().then(function(txt){
      if(!res.ok){
        var msg=txt;
        try{var j=JSON.parse(txt);if(j.error&&j.error.message)msg=j.error.message;else if(j.message)msg=j.message;}catch(e){}
        var er=new Error(msg);er.status=res.status;throw er;
      }
      var data=JSON.parse(txt);
      /* 프록시가 {text:"..."} 또는 표준 {content:[...]} 둘 다 허용 */
      if(typeof data.text==='string')return data.text;
      var out=(data.content||[]).filter(function(b){return b.type==='text';}).map(function(b){return b.text;}).join('\n');
      return out;
    });
  });
}

/* ════════ 마크다운 렌더 ════════ */
function inlineMd(s){s=esc(s);s=s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');return s;}
function renderMd(md){
  var lines=String(md==null?'':md).replace(/\r/g,'').split('\n');
  var out=[],inList=false,listClass='';
  function close(){if(inList){out.push('</ul>');inList=false;listClass='';}}
  function isTableSep(s){return /^\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?$/.test(s);}
  function cells(s){var x=s.trim().replace(/^\|/,'').replace(/\|$/,'');return x.split('|').map(function(c){return c.trim();});}
  function calloutType(s){
    if(/^(⚠️|주의|경고|리스크|위험)/.test(s))return ['c-warn','⚠️'];
    if(/^(✅|좋|개선|강점|충분)/.test(s))return ['c-ok','✅'];
    if(/^(💡|팁|tip|참고)/i.test(s))return ['c-tip','💡'];
    return ['c-key','📌'];
  }
  for(var i=0;i<lines.length;i++){
    var raw=lines[i],t=raw.trim();
    if(t===''){close();continue;}
    if(/^---+$/.test(t)||/^___+$/.test(t)){close();out.push('<hr>');continue;}
    // table
    if(/^\|.*\|/.test(t)&&i+1<lines.length&&isTableSep(lines[i+1].trim())){
      close();var head=cells(t);i+=2;var rows=[];
      while(i<lines.length&&/^\|?.*\|/.test(lines[i].trim())&&lines[i].trim()!==''){rows.push(cells(lines[i].trim()));i++;}
      i--;
      var th='<tr>'+head.map(function(c){return '<th>'+inlineMd(c)+'</th>';}).join('')+'</tr>';
      var tb=rows.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+inlineMd(c)+'</td>';}).join('')+'</tr>';}).join('');
      out.push('<table><thead>'+th+'</thead><tbody>'+tb+'</tbody></table>');continue;
    }
    // blockquote -> callout
    if(/^>\s?/.test(t)){
      close();var buf=[];
      while(i<lines.length&&/^>\s?/.test(lines[i].trim())){buf.push(lines[i].trim().replace(/^>\s?/,''));i++;}
      i--;var body=buf.join(' ');var ct=calloutType(body);
      var clean=body.replace(/^(⚠️|✅|💡|📌)\s*/,'');
      out.push('<div class="callout '+ct[0]+'"><span class="co-ic">'+ct[1]+'</span><div>'+inlineMd(clean)+'</div></div>');continue;
    }
    var hm=t.match(/^(#{1,5})\s+(.*)$/);
    if(hm){close();var lvl=Math.min(hm[1].length+2,5);out.push('<h'+lvl+'>'+inlineMd(hm[2])+'</h'+lvl+'>');continue;}
    var bm=t.match(/^[-*•]\s+(.*)$/);
    if(bm){if(!inList||listClass!=='ul'){close();out.push('<ul>');inList=true;listClass='ul';}out.push('<li>'+inlineMd(bm[1])+'</li>');continue;}
    var nm=t.match(/^(\d+)[.)]\s+(.*)$/);
    if(nm){if(!inList||listClass!=='ol'){close();out.push('<ul class="ol">');inList=true;listClass='ol';}out.push('<li><strong>'+nm[1]+'.</strong> '+inlineMd(nm[2])+'</li>');continue;}
    close();out.push('<p>'+inlineMd(t)+'</p>');
  }
  close();
  return out.join('');
}
/* 리포트 셸: 브랜드 표지 + 본문 + 푸터 (고객 전달용) */
