function runGen(id){
  var g=null;GEN.forEach(function(x){if(x.id===id)g=x;});
  if(!g)return;
  var v=collectVals(g);
  // 필수 첫 필드 체크
  var first=g.fields[0];
  if((first.type==='text'||first.type==='textarea')&&!v[first.name]){toast('"'+first.label+'"을(를) 입력해주세요');return;}
  if(!aiReady()){
    showRes(id,'<div class="err-box">🔌 AI 생성을 쓰려면 <b>연결 설정</b>이 필요합니다. <a style="color:#1A56DB;font-weight:800;text-decoration:underline" onclick="go(\'settings\')">설정</a>에서 <b>내 API 키</b>를 넣거나 <b>서버 프록시</b>를 연결하세요.<br><span style="color:#6B7280">※ 재무설계 계산기와 실무 계산기는 연결 없이 바로 쓸 수 있습니다.</span></div>',true);
    return;
  }
  var spec=g.build(v);
  var res=$('res_'+id);res.classList.add('on');
  res.innerHTML='<div class="loading"><div class="spinner"></div>APEX-YUNPRO 톤으로 '+esc(g.title)+' 생성 중…</div>';
  callClaude(spec.system,spec.user,spec.max).then(function(out){
    showRes(id,renderResultBlock(g.title,out,id),false);
    res._raw=out;
  }).catch(function(e){
    var msg;
    if(e.message==='NO_KEY')msg='연결이 설정되지 않았습니다. 설정에서 API 키 또는 프록시를 연결하세요.';
    else if(e.status===401||e.status===403)msg='인증에 실패했습니다('+e.status+'). 설정에서 API 키(또는 프록시 키)를 다시 확인하세요.';
    else if(e.status===429)msg='요청이 많습니다(429). 잠시 후 다시 시도하세요.';
    else if(e.status===400&&/model/i.test(e.message))msg='모델명이 올바르지 않을 수 있습니다. 설정에서 모델을 바꿔보세요.\n('+esc(e.message)+')';
    else if(e.status===501||e.status===405||/unsupported method|method not allowed/i.test(e.message||''))msg='이 주소는 AI 요청(POST)을 받지 못합니다. 미리보기(정적) 서버이거나 프록시가 아직 연결되지 않은 상태예요.\n→ 설정에서 <b>내 API 키</b>를 넣거나, 배포된 <b>서버 프록시 주소</b>(예: https://사이트/api/generate)를 연결하세요.';
    else msg='생성 실패: '+esc(e.message||'네트워크 오류')+'\n(브라우저 보안 정책으로 차단된 경우, 배포 환경에서 다시 시도하세요.)';
    showRes(id,'<div class="err-box">'+msg.replace(/\n/g,'<br>')+'</div>',true);
  });
}

function renderResultBlock(title,out,id){
  return '<div class="result-hd"><span class="rl">결과 · '+esc(title)+'</span>'+
    '<div class="btn-row"><button class="btn btn-ghost" onclick="copyRes(\''+id+'\')">📋 복사</button>'+
    '<button class="btn btn-ghost" onclick="runGen(\''+id+'\')">🔄 재생성</button></div></div>'+
    '<div class="result-body">'+renderMd(out)+'</div>';
}
function showRes(id,html,isErr){
  var res=$('res_'+id);res.classList.add('on');
  if(isErr)res.innerHTML='<div class="result-hd"><span class="rl">알림</span></div><div class="result-body">'+html+'</div>';
  else res.innerHTML=html;
}
function copyRes(id){var res=$('res_'+id);copyText(res._raw||res.querySelector('.result-body').innerText||'');}

