function richCtx(v){
  var L=[];function add(k,lab){if(v[k]&&v[k]!=='선택 안함'&&v[k]!=='자동')L.push(lab+': '+v[k]);}
  add('cat','보험종류');add('life','라이프스테이지');add('age','연령대');add('sex','성별');
