/* ════════ Gemini API (무료 티어) ════════ */
function callGemini(system,user,maxTokens){
  var key=getGeminiKey();
  if(!key)return Promise.reject(new Error('NO_KEY'));
  var url='https://generativelanguage.googleapis.com/v1beta/models/'+getGeminiModel()+':generateContent?key='+encodeURIComponent(key);
  var payload={
    systemInstruction:{parts:[{text:system}]},
    contents:[{role:'user',parts:[{text:user}]}],
    generationConfig:{maxOutputTokens:maxTokens||2000,temperature:0.7}
  };
  return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(function(res){
    return res.text().then(function(txt){
      if(!res.ok){
        var msg=txt;
        try{var j=JSON.parse(txt);if(j.error&&j.error.message)msg=j.error.message;}catch(e){}
        var er=new Error(msg);er.status=res.status;throw er;
      }
      var data=JSON.parse(txt);
      var cand=(data.candidates&&data.candidates[0])?data.candidates[0]:null;
      if(!cand||!cand.content||!cand.content.parts){
        var blk=(data.promptFeedback&&data.promptFeedback.blockReason)?data.promptFeedback.blockReason:'';
        throw new Error(blk?('Gemini가 응답을 차단했습니다('+blk+').'):'Gemini 응답이 비어 있습니다.');
      }
      return cand.content.parts.map(function(p){return p.text||'';}).join('\n');
    });
  });
}

/* ════════ 공급자 라우터: 도구 id에 맞는 공급자로 호출 ════════ */
function callAI(system,user,maxTokens,genId){
  var prov=providerForGen(genId);
  return prov==='gemini'?callGemini(system,user,maxTokens):callClaude(system,user,maxTokens);
}

