content.content:
3133	/* ════════ APEX 상담 OS — 로그인 셸 (Phase 1) ════════
3134	   기존 무키 도구(계산기·생성기·재무설계)는 그대로 유지한다.
3135	   로그인하면 고객 보장분석 프로젝트 계층(Phase 2~)이 열린다.
3136	   네트워크/CDN 없는 jsdom 스모크에서도 절대 부팅을 깨지 않도록 전부 방어적. */
3137	var OS={sb:null,session:null,profile:null};
3138	function osClient(){
3139	  if(OS.sb)return OS.sb;
3140	  if(typeof window==='undefined')return null;
3141	  if(!window.supabase||!window.APEX_SB)return null;
3142	  try{OS.sb=window.supabase.createClient(window.APEX_SB.url,window.APEX_SB.key);}
3143	  catch(e){OS.sb=null;}
3144	  return OS.sb;
3145	}
3146	function osRoleLabel(r){
3147	  return r==='admin'?'관리자':(r==='branch_manager'?'본부장':(r==='education_manager'?'교육매니저':(r==='leader'?'지점장':'설계사')));
3148	}
3149	/* 현재 역할(미로그인은 설계사 기준으로 기존 도구 회귀 방지) */
3150	function osRole(){return (OS.profile&&OS.profile.role)||'member';}
3151	function osIsLead(r){r=r||osRole();return r==='leader'||r==='branch_manager'||r==='admin';}
3152	function osIsHQ(r){r=r||osRole();return r==='branch_manager'||r==='admin';}
3153	function osIsEdu(r){r=r||osRole();return r==='education_manager'||r==='admin';}
3154	/* 역할별 노출 그룹 필터 (그룹에 role:'lead'|'hq'|'edu' 지정 시 해당 권한만) */
3155	function visibleTabs(role){
3156	  role=role||osRole();
3157	  return TABS.filter(function(g){
3158	    if(g.role==='lead')return osIsLead(role);
3159	    if(g.role==='hq')return osIsHQ(role);
3160	    if(g.role==='edu')return osIsEdu(role)||osIsHQ(role);
3161	    return true;
3162	  });
3163	}
3164	function osEsc(s){return (''+(s==null?'':s)).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
3165	function osVal(id){var el=document.getElementById(id);return el?el.value:'';}
3166	
3167	function osRenderPill(){
3168	  var foot=document.querySelector('.sb-foot');if(!foot)return;
3169	  var pill=document.getElementById('osAuthPill');
3170	  if(!pill){pill=document.createElement('div');pill.id='osAuthPill';pill.className='os-authpill';pill.onclick=osPillClick;foot.insertBefore(pill,foot.firstChild);}
3171	  if(OS.profile){
3172	    var nm=OS.profile.name||(OS.session&&OS.session.user&&OS.session.user.email)||'로그인됨';
3173	    pill.className='os-authpill on';
3174	    pill.innerHTML='<span class="dot"></span><span class="who">'+osEsc(nm)+'</span><span class="role">'+osRoleLabel(OS.profile.role)+'</span>';
3175	    pill.title='클릭하여 로그아웃';
3176	  }else{
3177	    pill.className='os-authpill';
3178	    pill.innerHTML='<span class="dot"></span><span class="who">로그인 / 계정</span>';
3179	    pill.title='로그인';
3180	  }
3181	}
3182	function osPillClick(){if(OS.profile)osLogout();else osOpenModal();}
3183	
3184	var osMode='login';
3185	function osModalHtml(){
3186	  return '<div class="os-modal">'+
3187	    '<button class="os-x" onclick="osCloseModal()">&times;</button>'+
3188	    '<div class="hd"><h3>APEX 상담 OS 로그인</h3><p>설계사 계정으로 로그인하면 고객 보장분석 프로젝트가 열립니다.</p></div>'+
3189	    '<div class="bd">'+
3190	      '<div class="os-tabs"><button id="osTabLogin" class="on" onclick="osAuthTab(\'login\')">로그인</button><button id="osTabSignup" onclick="osAuthTab(\'signup\')">계정 등록</button></div>'+
3191	      '<div class="os-fld" id="osNameFld" style="display:none"><label>이름</label><input id="osName" placeholder="홍길동"/></div>'+
3192	      '<div class="os-fld"><label>이메일</label><input id="osEmail" type="email" placeholder="you@example.com" autocomplete="username"/></div>'+
3193	      '<div class="os-fld"><label>비밀번호</label><input id="osPw" type="password" placeholder="••••••••" autocomplete="current-password"/></div>'+
3194	      '<div class="os-err" id="osErr"></div>'+
3195	      '<button class="os-btn" id="osSubmit" onclick="osSubmit()">로그인</button>'+
3196	    '</div></div>';
3197	}
3198	function osOpenModal(){
3199	  var ovl=document.getElementById('osOvl');
3200	  if(!ovl){ovl=document.createElement('div');ovl.id='osOvl';ovl.className='os-ovl';ovl.innerHTML=osModalHtml();document.body.appendChild(ovl);
3201	    ovl.addEventListener('click',function(e){if(e.target===ovl)osCloseModal();});}
3202	  ovl.classList.add('on');osAuthTab('login');
3203	  var em=document.getElementById('osEmail');if(em)em.focus();
3204	}
3205	function osCloseModal(){var o=document.getElementById('osOvl');if(o)o.classList.remove('on');}
3206	function osAuthTab(m){
3207	  osMode=m;
3208	  var l=document.getElementById('osTabLogin'),s=document.getElementById('osTabSignup');
3209	  if(l)l.className=(m==='login'?'on':'');if(s)s.className=(m==='signup'?'on':'');
3210	  var nf=document.getElementById('osNameFld');if(nf)nf.style.display=(m==='signup'?'block':'none');
3211	  var b=document.getElementById('osSubmit');if(b)b.textContent=(m==='signup'?'계정 등록':'로그인');
3212	  osErr('');
3213	}
3214	function osErr(msg){var e=document.getElementById('osErr');if(e)e.textContent=msg||'';}
3215	function osLoginErr(m){if(/Invalid login/i.test(m||''))return '이메일 또는 비밀번호가 올바르지 않습니다.';if(/Email not confirmed/i.test(m||''))return '이메일 인증이 완료되지 않았습니다.';return m;}
3216	function osSubmit(){
3217	  var sb=osClient();if(!sb){osErr('서버 연결 모듈을 불러오지 못했습니다. 네트워크를 확인하세요.');return;}
3218	  var email=(osVal('osEmail')||'').trim(),pw=osVal('osPw');
