(function(){
var sql = [
"-- SECTION A 진단 (읽기 전용) : 회원가입 실패 원인 파악",
"select jsonb_pretty(jsonb_build_object(",
"  'triggers_on_auth_users', (select jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'def',pg_get_triggerdef(t.oid)))",
"     from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace",
"     where n.nspname='auth' and c.relname='users' and not t.tgisinternal),",
"  'handle_new_user_src', (select pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace",
"     where n.nspname='public' and p.proname='handle_new_user'),",
"  'profiles_columns', (select jsonb_agg(jsonb_build_object('col',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) order by ordinal_position)",
"     from information_schema.columns where table_schema='public' and table_name='profiles'),",
"  'profiles_check_constraints', (select jsonb_agg(jsonb_build_object('name',con.conname,'def',pg_get_constraintdef(con.oid)))",
"     from pg_constraint con join pg_class rel on rel.oid=con.conrelid join pg_namespace n on n.oid=rel.relnamespace",
"     where n.nspname='public' and rel.relname='profiles' and con.contype='c')",
")) as diagnostics;"
].join("\n");
window.monaco.editor.getModels()[0].setValue(sql);
return "SET_OK len="+sql.length;
})()

(function(){
  // 결과 그리드에서 diagnostics 셀 전체 텍스트 추출 시도
  var txt='';
  var sel=['[role="gridcell"]','.ag-cell','[data-testid*="cell"]','.supabase-grid'];
  for(var i=0;i<sel.length;i++){var els=document.querySelectorAll(sel[i]);for(var j=0;j<els.length;j++){var t=els[j].innerText||els[j].textContent||'';if(t.indexOf('col')>-1||t.indexOf('trigger')>-1||t.length>200){txt+= '\n---['+sel[i]+']---\n'+t;}}}
  return txt.slice(0,4000)||'(no match) bodyLen='+document.body.innerText.length;
})()

