        '<div style="font-size:11px;color:#9CA3AF;margin-top:8px">근거: '+osEsc(a.s.ev)+'</div>'+
        '<div style="font-size:11.5px;font-weight:700;color:#1A56DB;margin-top:6px">바로가기 →</div>'+
      '</button>';
    });
    h+='</div>';
  }else{
    h+='<div class="osc-panel" style="text-align:center;color:#059669"><div style="font-size:26px">✅</div><div style="font-size:14px;font-weight:800;margin-top:6px">지금 즉시 처리할 항목이 없습니다.</div><div style="font-size:12px;color:#6B7280;margin-top:4px">데이터 기준으로 밀린 업무가 없습니다. 고객·상담·학습을 이어가세요.</div></div>';
  }
  if(quiet.length){
    h+='<div style="font-size:12px;font-weight:700;color:#6B7280;margin:16px 0 8px">확인 완료 · 0건</div><div style="display:flex;flex-wrap:wrap;gap:6px">';
    quiet.forEach(function(s){h+='<span style="font-size:11.5px;color:#6B7280;background:#F3F4F6;border-radius:20px;padding:4px 11px">'+s.icon+' '+osEsc(s.label)+' 0</span>';});
    h+='</div>';
  }
  if(skip){
