(function(){
  var out={};
  try{
    var keys=[]; for(var i=0;i<localStorage.length;i++){keys.push(localStorage.key(i));}
    out.lsKeys=keys;
    out.sbAuthKeys=keys.filter(function(k){return k.indexOf('sb-')===0||k.indexOf('supabase')>=0;});
  }catch(e){out.ls='ERR:'+e.message;}
