  return JSON.stringify(out);
})()

(function(){
  // error collector
  window.__errs=[]; window.onerror=function(m,s,l,c,e){window.__errs.push(String(m));};
  // find main content container
  var cont=document.getElementById('dyn')||document.getElementById('app')||document.querySelector('main')||document.body;
  window.__cont=cont;
  var allTabs=[]; TABS.forEach(function(g){g.items.forEach(function(it){allTabs.push(it.id);});});
  var results=[];
  allTabs.forEach(function(t){
    if(t==='finance'){results.push({tab:t, sig:'finance-iframe(skip in loop)'});return;}
    var before=window.__errs.length;
    var txt='', err='';
    try{ go(t); }catch(e){ err='THROW:'+e.message; }
    try{ txt=(cont.innerText||'').replace(/\s+/g,' ').trim(); }catch(e){}
    var thrown=window.__errs.slice(before);
    var sig;
    if(err)sig=err;
    else if(thrown.length)sig='JSERR:'+thrown[0];
    else if(/로그인이 필요|로그인 후|로그인하면/.test(txt))sig='LOGIN_GATE';
    else if(/연결.*필요|API.*키|키를 입력|Gemini 연결|Claude 연결/.test(txt))sig='NEEDS_AI_KEY';
    else if(txt.length<20)sig='EMPTY('+txt.length+')';
    else sig='OK('+txt.length+') :: '+txt.slice(0,70);
    results.push({tab:t, sig:sig});
  });
  return JSON.stringify(results,null,1);
})()

