var OS={sb:null,session:null,profile:null};
function osClient(){
  if(OS.sb)return OS.sb;
  if(typeof window==='undefined')return null;
  if(!window.supabase||!window.APEX_SB)return null;
  try{OS.sb=window.supabase.createClient(window.APEX_SB.url,window.APEX_SB.key);}
  catch(e){OS.sb=null;}
  return OS.sb;
}
function osRoleLabel(r){
  return r==='admin'?'관리자':(r==='branch_manager'?'본부장':(r==='education_manager'?'교육매니저':(r==='leader'?'지점장':'설계사')));
}
/* 현재 역할(미로그인은 설계사 기준으로 기존 도구 회귀 방지) */
function osRole(){return (OS.profile&&OS.profile.role)||'member';}
function osIsLead(r){r=r||osRole();return r==='leader'||r==='branch_manager'||r==='admin';}
function osIsHQ(r){r=r||osRole();return r==='branch_manager'||r==='admin';}
function osIsEdu(r){r=r||osRole();return r==='education_manager'||r==='admin';}
/* 역할별 노출 그룹 필터 (그룹에 role:'lead'|'hq'|'edu' 지정 시 해당 권한만) */
function visibleTabs(role){
  role=role||osRole();
  return TABS.filter(function(g){
    if(g.role==='lead')return osIsLead(role);
    if(g.role==='hq')return osIsHQ(role);
    if(g.role==='edu')return osIsEdu(role)||osIsHQ(role);
    return true;
  });
}
function osEsc(s){return (''+(s==null?'':s)).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
