function osLoginErr(m){if(/Invalid login/i.test(m||''))return '이메일 또는 비밀번호가 올바르지 않습니다.';if(/Email not confirmed/i.test(m||''))return '이메일 인증이 완료되지 않았습니다.';return m;}
function osSubmit(){
  var sb=osClient();if(!sb){osErr('서버 연결 모듈을 불러오지 못했습니다. 네트워크를 확인하세요.');return;}
  var email=(osVal('osEmail')||'').trim(),pw=osVal('osPw');
  if(!email||!pw){osErr('이메일과 비밀번호를 입력하세요.');return;}
  var btn=document.getElementById('osSubmit');if(btn){btn.disabled=true;btn.textContent='처리 중…';}
