      osErr('');toast('계정이 생성되었습니다. 관리자 승인 후 이용하세요.');osAuthTab('login');
    });
  }else{
    sb.auth.signInWithPassword({email:email,password:pw}).then(function(r){
      done();if(r.error){osErr(osLoginErr(r.error.message));return;}osCloseModal();
    });
  }
}
