    try{var raw=localStorage.getItem('apex_audit_ring');var ring=raw?JSON.parse(raw):[];ring.unshift(entry);if(ring.length>200)ring=ring.slice(0,200);localStorage.setItem('apex_audit_ring',JSON.stringify(ring));}catch(e){}
