  var cont=window.__cont||document.getElementById('dyn')||document.body;
  window.__errs=[]; window.onerror=function(m){window.__errs.push(String(m));};
  var gated=['home','assistant','growth','clients','interpret','claims','branch_coach','hq','audit','wallets','contracts'];
  var res=[];
  gated.forEach(function(t){
    var before=window.__errs.length; var txt='',err='';
    try{ go(t); }catch(e){ err='THROW:'+e.message; }
    try{ txt=(cont.innerText||'').replace(/\s+/g,' ').trim(); }catch(e){}
    var thrown=window.__errs.slice(before);
    var c = err?('THROW:'+err):(thrown.length?('JSERR:'+thrown[0].slice(0,80)):(/로그인이 필요|로그인 후/.test(txt)?'STILL_GATED':(txt.length<25?'EMPTY':'RENDER_OK')));
    res.push({tab:t, r:c, peek:txt.slice(0,55)});
  });
  return JSON.stringify(res,null,1);
})()

