  return Promise.all(tables.map(function(t){
    return sb.from(t).select('id',{count:'exact',head:true}).then(function(r){
      if(r.error){return t+' => ERR('+(r.error.code||'?')+':'+String(r.error.message).slice(0,40)+')';}
      return t+' => OK(count='+(r.count==null?'?':r.count)+')';
