1401	  var bin=atob(b64),bytes=new Uint8Array(bin.length);
1402	  for(var i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
1403	  try{return new TextDecoder('utf-8').decode(bytes);}
1404	  catch(e){return decodeURIComponent(escape(bin));}
