/* ════════ 조직도 (로컬 저장 · 키·로그인 불필요) ════════ */
var ORG_KEY='apex_org_chart';
var orgEditId=null;
function orgSeed(){return [{id:'m_hq',name:'윤시현',rank:'본부장',team:'온탑본부',parent:'',phone:'',insta:'',photo:''}];}
function orgLoad(){
  try{var raw=localStorage.getItem(ORG_KEY);if(raw){var a=JSON.parse(raw);if(a&&a.length)return a;}}catch(e){}
  return orgSeed();
}
function orgSave(list){
  try{localStorage.setItem(ORG_KEY,JSON.stringify(list));return true;}
  catch(e){alert('저장 공간이 부족합니다. 사진 용량이 큰 구성원의 사진을 제거하거나 다시 선택해 주세요.');return false;}
}
function orgVal(id){var e=document.getElementById(id);return e?(''+e.value).replace(/^\s+|\s+$/g,''):'';}
function orgInsta(v){return (''+v).replace(/^@/,'').replace(/https?:\/\/(www\.)?instagram\.com\//i,'').replace(/[\/?#].*$/,'').replace(/^\s+|\s+$/g,'');}
function orgRankColor(r){
  var m={'본부장':'#0F172A','지점장':'#1A56DB','팀장':'#7C3AED','설계사':'#0891B2','신입':'#059669'};
  return m[r]||'#6B7280';
}
function orgPhotoPick(input){
  var f=input&&input.files&&input.files[0];if(!f)return;
  if(f.size>12*1024*1024){alert('12MB 이하 이미지를 선택해 주세요.');return;}
  var rd=new FileReader();
  rd.onload=function(e){
    var img=new Image();
    img.onload=function(){
      var max=180,w=img.width,h=img.height,scale=Math.min(1,max/Math.max(w,h));
      var cw=Math.max(1,Math.round(w*scale)),ch=Math.max(1,Math.round(h*scale));
      var cv=document.createElement('canvas');cv.width=cw;cv.height=ch;
      cv.getContext('2d').drawImage(img,0,0,cw,ch);
      var url=cv.toDataURL('image/jpeg',0.82);
      window.__orgPhoto=url;
      var pv=document.getElementById('orgPhotoPv');if(pv){pv.src=url;pv.style.display='';}
    };
    img.src=e.target.result;
  };
  rd.readAsDataURL(f);
}
function orgPhotoClear(){window.__orgPhoto='';var pv=document.getElementById('orgPhotoPv');if(pv){pv.src='';pv.style.display='none';}}
function orgAdd(){orgEditId=null;window.__orgPhoto=undefined;go('org');}
function orgEdit(id){orgEditId=id;window.__orgPhoto=undefined;go('org');var c=document.getElementById('orgFormCard');if(c)c.scrollIntoView();}
function orgCancel(){orgEditId=null;window.__orgPhoto=undefined;go('org');}
function orgDelete(id){
  if(!confirm('이 구성원을 삭제할까요? 하위 구성원은 상위자에게 자동 연결됩니다.'))return;
  var list=orgLoad(),removed=null,i;
  for(i=0;i<list.length;i++){if(list[i].id===id){removed=list[i];break;}}
  var np=removed?removed.parent:'';
  var out=[];
  for(i=0;i<list.length;i++){
    if(list[i].id===id)continue;
    if(list[i].parent===id)list[i].parent=np;
    out.push(list[i]);
  }
  orgSave(out);if(orgEditId===id)orgEditId=null;go('org');
}
function orgReset(){
  if(!confirm('조직도를 초기화할까요? 저장된 구성원이 모두 삭제됩니다.'))return;
  try{localStorage.removeItem(ORG_KEY);}catch(e){}
  orgEditId=null;window.__orgPhoto=undefined;go('org');
}
function orgSubmit(){
  var name=orgVal('org_f_name');
  if(!name){alert('이름을 입력하세요.');return;}
  var rank=orgVal('org_f_rank')||'설계사';
  var team=orgVal('org_f_team');
  var parent=orgVal('org_f_parent');
  var phone=orgVal('org_f_phone');
  var insta=orgInsta(orgVal('org_f_insta'));
  var list=orgLoad(),i,cur=null;
  if(orgEditId){for(i=0;i<list.length;i++){if(list[i].id===orgEditId){cur=list[i];break;}}}
  var photo;
  if(typeof window.__orgPhoto!=='undefined')photo=window.__orgPhoto;
  else if(cur)photo=cur.photo||'';
  else photo='';
  if(parent===orgEditId)parent='';
  if(cur){cur.name=name;cur.rank=rank;cur.team=team;cur.parent=parent;cur.phone=phone;cur.insta=insta;cur.photo=photo;}
  else{list.push({id:'m_'+Date.now()+'_'+Math.floor(Math.random()*1000),name:name,rank:rank,team:team,parent:parent,phone:phone,insta:insta,photo:photo});}
  if(orgSave(list)){orgEditId=null;window.__orgPhoto=undefined;go('org');}
}
function orgPhotoTag(m,size,idAttr){
  var s=size||52;
  if(m&&m.photo)return '<img'+(idAttr?' id="'+idAttr+'"':'')+' src="'+m.photo+'" alt="" style="width:'+s+'px;height:'+s+'px;border-radius:50%;object-fit:cover;flex:none">';
  var ini=osEsc(((m&&m.name)||'?').charAt(0));
  return '<div style="width:'+s+'px;height:'+s+'px;border-radius:50%;background:var(--primary-light);color:var(--primary);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:'+Math.round(s/2.7)+'px;flex:none">'+ini+'</div>';
}
function orgCard(m){
  var phone=m.phone?'<a href="tel:'+(''+m.phone).replace(/[^0-9+]/g,'')+'" style="color:var(--primary);text-decoration:none">📞 '+osEsc(m.phone)+'</a>':'<span style="color:var(--ink-5)">📞 —</span>';
  var insta=m.insta?'<a href="https://instagram.com/'+encodeURIComponent(m.insta)+'" target="_blank" rel="noopener" style="color:#7C3AED;text-decoration:none">📸 @'+osEsc(m.insta)+'</a>':'<span style="color:var(--ink-5)">📸 —</span>';
  return '<div class="card" style="margin:8px 0;display:flex;align-items:center;gap:12px;padding:11px 14px">'
    + orgPhotoTag(m,52)
    + '<div style="flex:1;min-width:0">'
      + '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">'
        + '<b style="font-size:15px">'+osEsc(m.name)+'</b>'
        + '<span class="badge" style="background:'+orgRankColor(m.rank)+';color:#fff">'+osEsc(m.rank)+'</span>'
        + (m.team?'<span style="font-size:12px;color:var(--ink-4)">'+osEsc(m.team)+'</span>':'')
      + '</div>'
      + '<div style="display:flex;gap:16px;margin-top:4px;font-size:12.5px;flex-wrap:wrap">'+phone+insta+'</div>'
    + '</div>'
    + '<div style="display:flex;gap:6px;flex:none">'
      + '<button class="btn btn-ghost" style="padding:5px 10px;font-size:12px" onclick="orgEdit(\''+m.id+'\')">편집</button>'
      + '<button class="btn btn-ghost" style="padding:5px 10px;font-size:12px;color:var(--neg)" onclick="orgDelete(\''+m.id+'\')">삭제</button>'
    + '</div></div>';
}
function orgTree(list){
  var byParent={},ids={},i;
  for(i=0;i<list.length;i++)ids[list[i].id]=list[i];
  for(i=0;i<list.length;i++){var m=list[i];var p=(m.parent&&ids[m.parent])?m.parent:'__root';(byParent[p]=byParent[p]||[]).push(m);}
  function node(m,depth){
    var kids=byParent[m.id]||[],h=orgCard(m);
    if(kids.length){
      h+='<div style="margin-left:16px;border-left:2px solid var(--primary-light);padding-left:12px">';
      for(var j=0;j<kids.length;j++)h+=node(kids[j],depth+1);
      h+='</div>';
    }
    return h;
  }
