    for(i=0;i<l3.length;i++){if(l3[i].id===afterPhoto.id)continue;if(l3[i].parent===afterPhoto.id)l3[i].parent=np;o3.push(l3[i]);}
    orgSave(o3);
    var kidAfter=orgLoad().filter(function(m){return m.name==='박신입';})[0];
    out.childReparented = kidAfter.parent==='m_hq';
    // cleanup: reset to clean seed
    localStorage.removeItem('apex_org_chart');
    orgEditId=null; window.__orgPhoto=undefined;
    go('org');
    out.afterResetCount = orgLoad().length;
    out.afterResetName = orgLoad()[0].name;
  }catch(e){out.error=e.message;}
  return JSON.stringify(out);
})();
